import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { adminUrl, createScratchDb, psql } from '../db/scratch-db';

// CI guard (issue #112). It reads the catalog of a database with every migration applied, so a
// migration that adds a table (or a function, or a view) and forgets row level security fails
// here, with the table named. Fix the migration, do not edit this file, unless the new table is a
// deliberate exception: then add it to the list below with the reason.

/** Tables without `club_id` and why each is safe. Anything else with no club_id fails the guard. */
const NO_CLUB_ID: Record<string, string> = {
  users:
    'people table: self, co-players, members of the session club (policies in 0160000/0230120)',
  auth_identities: 'own identities only; workers run as system',
  clubs: 'the club itself: directory for players, own row for club roles',
  ratings: 'follow the player between clubs: self, co-players, workers',
};

function rows<T>(url: string, sql: string): T[] {
  const out = psql(url, `SELECT coalesce(json_agg(t), '[]') FROM (${sql}) t`);
  return JSON.parse(out) as T[];
}

describe.skipIf(!adminUrl)('RLS catalog guard', () => {
  const db = adminUrl ? createScratchDb('rlsguard') : { url: '', drop: () => undefined };
  afterAll(() => db.drop());

  interface Table {
    name: string;
    rls: boolean;
    forced: boolean;
    has_club: boolean;
    policies: number;
    select_policies: number;
    immutable_trigger: boolean;
    support_audit: boolean;
  }
  let tables: Table[] = [];

  beforeAll(() => {
    tables = rows<Table>(
      db.url,
      `SELECT c.relname AS name, c.relrowsecurity AS rls, c.relforcerowsecurity AS forced,
         EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = c.oid AND a.attname = 'club_id'
                  AND NOT a.attisdropped) AS has_club,
         (SELECT count(*) FROM pg_policy p WHERE p.polrelid = c.oid)::int AS policies,
         (SELECT count(*) FROM pg_policy p WHERE p.polrelid = c.oid AND p.polcmd IN ('r', '*'))::int AS select_policies,
         EXISTS (SELECT 1 FROM pg_trigger g WHERE g.tgrelid = c.oid AND NOT g.tgisinternal
                  AND g.tgfoid = 'forbid_key_change'::regproc) AS immutable_trigger,
         EXISTS (SELECT 1 FROM pg_trigger g WHERE g.tgrelid = c.oid AND NOT g.tgisinternal
                  AND g.tgfoid = 'audit_support_write'::regproc) AS support_audit
       FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
       WHERE n.nspname = 'public' AND c.relkind IN ('r', 'p') AND c.relname <> '_prisma_migrations'
       ORDER BY 1`,
    );
  });

  it('sees the tables (sanity)', () => {
    expect(tables.length).toBeGreaterThan(35);
  });

  it('every table has RLS enabled AND forced', () => {
    expect(tables.filter((t) => !t.rls).map((t) => t.name)).toEqual([]);
    expect(tables.filter((t) => !t.forced).map((t) => t.name)).toEqual([]);
  });

  it('every table has at least one policy, and one that applies to SELECT', () => {
    expect(tables.filter((t) => t.policies === 0).map((t) => t.name)).toEqual([]);
    expect(tables.filter((t) => t.select_policies === 0).map((t) => t.name)).toEqual([]);
  });

  it('every table is scoped by club_id, or is a documented exception', () => {
    const unscoped = tables.filter((t) => !t.has_club).map((t) => t.name);
    expect(unscoped.sort()).toEqual(Object.keys(NO_CLUB_ID).sort());
  });

  it('club_id (and the parent keys) cannot be changed by an UPDATE', () => {
    expect(tables.filter((t) => t.has_club && !t.immutable_trigger).map((t) => t.name)).toEqual([]);
  });

  it('writes by internal support are audited by the database on every club table', () => {
    // users, auth_identities, ratings are person tables (support cannot write them: see the matrix).
    const exempt = new Set(['audit_log', 'users', 'auth_identities', 'ratings']);
    expect(
      tables.filter((t) => !exempt.has(t.name) && !t.support_audit).map((t) => t.name),
    ).toEqual([]);
  });

  it('policies apply only to app_runtime and none is a tautology', () => {
    const policies = rows<{ table: string; name: string; roles: string; expr: string }>(
      db.url,
      `SELECT tablename AS table, policyname AS name, roles::text AS roles,
              coalesce(qual, '') || ' ' || coalesce(with_check, '') AS expr
         FROM pg_policies WHERE schemaname = 'public'`,
    );
    expect(policies.length).toBeGreaterThan(50);
    expect(
      policies.filter((p) => p.roles !== '{app_runtime}').map((p) => `${p.table}.${p.name}`),
    ).toEqual([]);
    // Every expression must consult the session context (app_*() helpers) at least once.
    expect(
      policies
        .filter(
          (p) =>
            !/app_(user_id|club_id|role|club_ops|club_owner|is_support|plays|coaches|shares|is_member|booked|support)/.test(
              p.expr,
            ),
        )
        .map((p) => `${p.table}.${p.name}`),
    ).toEqual([]);
  });

  it('app_runtime is neither superuser, BYPASSRLS, a login role, nor the owner of anything', () => {
    const [role] = rows<{ rolsuper: boolean; rolbypassrls: boolean; rolcanlogin: boolean }>(
      db.url,
      `SELECT rolsuper, rolbypassrls, rolcanlogin FROM pg_roles WHERE rolname = 'app_runtime'`,
    );
    expect(role).toEqual({ rolsuper: false, rolbypassrls: false, rolcanlogin: false });
    const owned = rows<{ n: string }>(
      db.url,
      `SELECT c.relname AS n FROM pg_class c WHERE c.relowner = 'app_runtime'::regrole
        AND c.relnamespace = 'public'::regnamespace`,
    );
    expect(owned).toEqual([]);
  });

  it('app_runtime has no TRUNCATE/REFERENCES/TRIGGER, no access to migration history, audit_log is append-only', () => {
    const bad = rows<{ t: string; p: string }>(
      db.url,
      `SELECT c.relname AS t, p.priv AS p
         FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace,
              unnest(ARRAY['TRUNCATE', 'REFERENCES', 'TRIGGER']) p(priv)
        WHERE n.nspname = 'public' AND c.relkind = 'r' AND has_table_privilege('app_runtime', c.oid, p.priv)`,
    );
    expect(bad).toEqual([]);
    const [audit] = rows<{ u: boolean; d: boolean }>(
      db.url,
      `SELECT has_table_privilege('app_runtime', 'audit_log', 'UPDATE') AS u,
              has_table_privilege('app_runtime', 'audit_log', 'DELETE') AS d`,
    );
    expect(audit).toEqual({ u: false, d: false });
    const migrations = rows<{ x: boolean }>(
      db.url,
      `SELECT to_regclass('public._prisma_migrations') IS NULL
          OR NOT has_table_privilege('app_runtime', 'public._prisma_migrations', 'SELECT') AS x`,
    );
    expect(migrations[0]?.x).toBe(true);
  });

  it('SECURITY DEFINER functions pin search_path, are not callable by PUBLIC and are owned by a role that bypasses RLS', () => {
    const fns = rows<{
      name: string;
      definer: boolean;
      pinned: boolean;
      public_exec: boolean;
      owner_bypasses: boolean;
    }>(
      db.url,
      `SELECT p.proname AS name, p.prosecdef AS definer,
              coalesce(p.proconfig::text LIKE '%search_path=%', false) AS pinned,
              has_function_privilege('public', p.oid, 'EXECUTE') AS public_exec,
              (SELECT r.rolsuper OR r.rolbypassrls FROM pg_roles r WHERE r.oid = p.proowner) AS owner_bypasses
         FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
        WHERE n.nspname = 'public'
          AND NOT EXISTS (SELECT 1 FROM pg_depend d WHERE d.objid = p.oid AND d.deptype = 'e')`,
    );
    expect(fns.length).toBeGreaterThan(8);
    expect(fns.filter((f) => f.definer && !f.pinned).map((f) => f.name)).toEqual([]);
    expect(fns.filter((f) => f.definer && !f.owner_bypasses).map((f) => f.name)).toEqual([]);
    expect(fns.filter((f) => f.public_exec).map((f) => f.name)).toEqual([]);
  });

  it('there are no views that would run with the owner privileges (or they are security_invoker)', () => {
    const views = rows<{ name: string; invoker: boolean }>(
      db.url,
      `SELECT c.relname AS name, coalesce(c.reloptions::text LIKE '%security_invoker=true%', false) AS invoker
         FROM pg_class c WHERE c.relnamespace = 'public'::regnamespace AND c.relkind IN ('v', 'm')`,
    );
    expect(views.filter((v) => !v.invoker).map((v) => v.name)).toEqual([]);
  });
});
